{
    container:{},
    contextMenu:new SepoaContextMenuManager(),
    template:{
        itemWrapper:'<div class="file-item-container file-item-code-$.{FILE_ID}"></div>',
        //itemContents:'<div class="file-item-status file-item-status-$.{UPLOAD_STATUS} file-item-file-type-$.{FILE_TYPE}"><div class="file-item-btn xi-sepoa-dummy file-item-btn-delete xi-close-circle"></div><div class="file-item-contents"><div class="file-item-info"><div class="file-item-icon file-item-icon-$.{FILE_TYPE}"></div><div class="file-item-file-info"><div class="file-item-info-filename">$.{FILE_NAME_CLIENT}</div><div class="file-item-info-pagecount">$.{MESSAGE}</div></div></div><div class="file-item-progress-wrapper"><div class="file-item-progress"></div></div><div class="file-item-btn xi-sepoa-dummy file-item-btn-menu xi-ellipsis-v"></div></div></div>'
        itemContents:'<div class="file-item-status file-item-status-$.{UPLOAD_STATUS} file-item-file-type-$.{FILE_TYPE}"><div class="file-item-btn xi-sepoa-dummy file-item-btn-delete xi-close-circle"></div><div class="file-item-contents"><div class="file-item-info"><div class="file-item-icon file-item-icon-$.{FILE_TYPE}"></div><div class="file-item-file-info"><div class="file-item-info-filename">$.{FILE_NAME_CLIENT}</div><div class="file-item-info-pagecount">$.{MESSAGE}</div></div></div><div class="file-item-progress-wrapper"><div class="file-item-progress"></div></div></div></div>'
    }
