userscript.function:

callFunction('p', 'childScreenReady', [{
    name:'UPLOAD',
    id: $sObject.aliasCode, 
    fn:{
        doOpenDocument:doOpenDocument,
        doUpdateShare:doUpdateShare
    }
}]);


clearList();
$share.config = config;
$share.service = ({C:'contract',T:'contract.template'})[$share.config.module.WORK_TYPE];

drawFileUploadContainer();

var uploadTypeModules = sUtils.workflow.getChildren('CT1625541278864');
for(var i in uploadTypeModules){
    var moduleCode = uploadTypeModules[i];
    $share.uploadFileTypes[sUtils.workflow.getAlias(moduleCode)] = sUtils.workflow.getOptions(moduleCode, true);
}

// Before Module settings
$share.uploadFileTypes={
    C:['pdf','ppt','pptx','doc','docx','xls','xlsx','hwp','hwpx','jpg','png','jpeg','gif'],//Contract
    E:['pdf','ppt','pptx','doc','docx','xls','xlsx','hwp','hwpx','jpg','png','jpeg','gif'],//Quotation
    A:['*'],//Attachments
    B:['pdf','jpg','png','jpeg','gif'] //Business Registration 
}

if(!$share.config.document.CONT_NO) {
    $share.config.document.CONT_NO = getDocumentNumber("CT");
    $share.config.document.CONT_GL_SEQ = '1';
}else{
    doQuery();
}


// cont method select
contMethodTypeWrapper.classList.add('cont-method-type-wrapper');

//var selectWrapper = contMethodTypeWrapper.appendChild($('<div id="custom_select_wrapper" class="selectContain custom-select-wrapper"><select id="cont_method_box" class="cont_method_box"></select></div>')[0]);
//var methodBox = selectWrapper.children[0];
//var methodType = $share.config.module.AVAILABLE_CONT_METHOD || [];
//for(var i in methodType){
//    methodBox.appendChild($(sUtils.string.dataReplacer('<option id="cont_option_$.{TYPE}" class="cont_option_$.{TYPE}" value="$.{TYPE}">$LANG{CT_020.CONT_METHOD_$.{TYPE}}</option>', {TYPE:methodType[i]}))[0]);
//}
//$(methodBox).val("D");
//$(methodBox).trigger("change");
//sUtils.contract.element.customSelect(contMethodTypeWrapper);

// file list
$share.container.contractList = uploadFileListWrapper.appendChild($('<div class="file-list file-list-contract" sortable="true"></div>')[0]);
/*
$($share.container.contractList).sortable({
    axis: "y",
    containment: "parent"
});
*/
$share.container.exceptList = uploadFileListWrapper.appendChild($('<div class="file-list file-list-except" sortable="false"></div>')[0]);

// file upload container
contractFileDropContaier.classList.add('drop-container');
etcFileDropContainer.classList.add('drop-container');
contractFileDropWrapper.classList.add('drop-wrapper');
etcFileDropWrapper.classList.add('drop-wrapper');

var containerHTML = '<div id="$.{TYPE}_drop_zone_container" class="$.{TYPE}-drop-zone-container drop-zone-container""><div id="$.{TYPE}_drop_zone_outer" class="$.{TYPE}-drop-zone-outer drop-zone-outer"><div id="$.{TYPE}_drop_zone_inner" class="$.{TYPE}-drop-zone-inner drop-zone-inner"><div id="$.{TYPE}_drop_zone_image" class="$.{TYPE}-drop-zone-image drop-zone-image"></div><div id="$.{TYPE}_drop_zone_text" class="$.{TYPE}-drop-zone-text drop-zone-text">$LANG{POA_CONTRACT.LABEL_FILE_TYPE_$.{TYPE}}</div></div></div></div>';
['C', 'E', 'B', 'A'].forEach(function(type){
    if($share.config.module.AVAILABLE_FILE_TYPE.indexOf(type) >= 0){
        var cont = contractFileDropWrapper.appendChild($(sUtils.string.dataReplacer(containerHTML, {TYPE:type}))[0]);
        cont._data = {type:type}
        $(cont).on({
            click:function(e){
                doFileUpload(this._data);
            },
            drop:function(e){
                e.preventDefault();

                this.classList.remove('drop-zone-hover');
                var files = (e.dataTransfer || e.originalEvent.dataTransfer).files;
                if(files){
                    doFileUpload(this._data, files);
                }
            },
            dragenter:function(e){
                this.classList.add('drop-zone-hover');
                e.stopPropagation();
                e.preventDefault();
            },
            dragover:function(e){
                this.classList.add('drop-zone-hover');
                e.stopPropagation();
                e.preventDefault();
            },
            dragleave:function(e){
                this.classList.remove('drop-zone-hover');
                e.stopPropagation();
                e.preventDefault();
            }
        }) 
    }
});

const noneFileButton = sUtils.element.create(sUtils.string.dataReplacer(containerHTML, {TYPE : 'NONE_FILE'}));
noneFileButton.classList.add('none-file-drop');
noneFileButton.onclick = function(event) {
    callFunction("p", "doDocumentCreate", []);
    callFunction('p', 'onBeforeActive', ['MODULE', {id : 'UPLOAD'}]);
}
//contractFileDropWrapper.appendChild(noneFileButton);

//file list btn event
uploadFileListWrapper.addEventListener('click', function(e){
    var src = e.srcElement;
    if(src.classList.contains('file-item-btn')){
        var data = $(src).parents('.file-item-container')[0]._data;
        if(src.classList.contains('file-item-btn-delete')){
            doDeleteFile(data);
        }
        /*
        if(src.classList.contains('file-item-btn-menu')){
            var contextItems = {
                "rename" : {
                    "name": Sepoa.cache.text.get('CT_020.CONTEXT_MENU_RENAME'),
                    "callback" : onContextItemClick
                }
            };

            if(['C','E'].indexOf(data.FILE_TYPE) <= 0){
                contextItems.download = {
                    "name": Sepoa.cache.text.get('CT_020.CONTEXT_MENU_DOWNLOAD'),
                    "callback" : onContextItemClick
                }
                contextItems.preview = {
                    "name": Sepoa.cache.text.get('CT_020.CONTEXT_MENU_VIEW'),
                    "callback" : onContextItemClick
                }
            }
            $share.contextMenu.showContextMenu(src, {
                items: contextItems
            });
        }else if(src.classList.contains('file-item-btn-delete')){
            doDeleteFile(data);
        }
        */
    }
})


var fileItem = $share.container[(data.FILE_TYPE=='C')?'contractList':'exceptList'].appendChild($(sUtils.string.dataReplacer($share.template.itemWrapper, data))[0]);
fileItem.appendChild($(sUtils.string.dataReplacer($share.template.itemContents, data))[0]);
fileItem._data = data;


var clazzName = 'file-item-code-'+(data.TEMP_FILE_ID || data.FILE_ID);
var fileItem = $(uploadFileListWrapper).find('.'+clazzName)[0];

fileItem._data = $.extend(fileItem._data, data);
fileItem.innerHTML = "";
fileItem.appendChild($(sUtils.string.dataReplacer($share.template.itemContents, fileItem._data))[0]);
fileItem.classList.remove(clazzName);
fileItem.classList.add('file-item-code-'+fileItem._data.FILE_ID);


var config={
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res, config, params){
            if(res.status == "1" && res.result){
                clearList();
                for(var i in res.result){
                    var data = res.result[i];
                    for(var i in data){
                        data[i].MESSAGE = (data[i].PAGE_COUNT || data[i].CONVERT_COUNT || "1") + "Pages";
                        drawFileRow(data[i]);
                    }
                }
            }
        }
    }
}

var params = {
    module:$share.service,
    action: "doFileList",
    CONNECTION: "TRANSACTION",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ
}
sUtils.multipart.send(config, params);


var config = {
    multiple:true,
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    ext:$share.uploadFileTypes[data.type],
    on:{
        callback:function(res, config, params){
            var result = $.extend(true, {}, params);
            if(res.status == "1"){
                $.extend(result, res.result[0]);
                result.UPLOAD_STATUS = "";
                result.MESSAGE = (result.PAGE_COUNT || result.CONVERT_COUNT) + " Pages";
            }else{
                result.UPLOAD_STATUS = "ERROR";
                result.MESSAGE = sUtils.cache.text.get('CT_020.UPLOAD_FAIL_ETC');
            }
            updateFileStatus(result);
        },
        beforeSend:function(config, params, files, idx){
            params.FILE_ID = "TEMP_"+sUtils.date.getTimeString();
            params.UPLOAD_STATUS = "WAITING"
            drawFileRow($.extend(true, params, {FILE_NAME_CLIENT:files.name}), true);
        }
    },
    foreach:true
}
if(data.type != "C"){
    config.multiple = false;

    //check already file
    if($('.file-item-file-type-'+data.type).length > 0){
        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0011'));
        return;
    }

}

var params = {
    module:$share.service,
    action: "doFileUpload",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ,
    CONT_TYPE: $share.config.document.CONT_TYPE,
    FILE_TYPE:data.type
}
if(files){
    params.files = files
}

if(callFunction("p", "doDocumentCreate", [])){
    sUtils.multipart.upload(config, params);
}else{
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0012'));
}


sUtils.popup.modal({
    url:window.CONTEXT_NAME+'/Contract/Common/ContractCommonInputwindow.sux',
    width:350,
    height:150,
    title:sUtils.cache.text.get('POA_CONTRACT.TITLE_RENAME'),
    params:{
        callback:function(newFileName){
            var config = {
                url:window.CONTEXT_NAME+'/SepoaActionController.sux',
                on:{
                    callback:function(res){
                        if(res.status == "1"){
                            updateFileStatus({FILE_NAME_CLIENT:newFileName, FILE_ID:data.FILE_ID})
                        }else{
                            Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0013'));
                        }
                    }
                }
            }

            var params = {
                module:$share.service,
                action: "doFileNameUpdate",
                FILE_ID : data.FILE_ID,
                NEW_FILE_NAME:newFileName
            }

            sUtils.multipart.send(config, params);  
        }
    }
})


var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux'
}

var params = {
    module:$share.service,
    action: "doFileDownload",
    CONNECTION: "CONNECTION",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ,
    CONT_TYPE: $share.config.document.CONT_TYPE,
    FILE_ID : data.FILE_ID,
    ORIGIN:"Y"
}

sUtils.multipart.download(config, params);


if(['C', 'E'].indexOf(data.FILE_TYPE) < 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0014'));
    return;
}

PopupOpenPost('/Contract/Module/ContractModuleTabbar.sux', {
    view : 'VIEW',
    data : {
        CONT_NO: $share.config.document.CONT_NO,
        CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ,
        CONT_TYPE: $share.config.document.CONT_TYPE,
        FILE_ID : data.FILE_ID,
        WORK_TYPE : $share.config.document.WORK_TYPE,
        DOCUMENT_TYPE : data.FILE_TYPE,
        SINGLE_PREVIEW : true
    }
} , null, 950, 800, sUtils.cache.text.get('POA_CONTRACT.TITLE_PREVIEW_FILE'))


var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res){
            if(res.status == "1"){
                var fileItem = $(uploadFileListWrapper).find('.file-item-code-'+data.FILE_ID);
                fileItem.slideUp(function(){
                    fileItem.remove();
                })
            }else{
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0015'));
            }
        }
    }
}

var params = {
    module:$share.service,
    action: "doFileDelete",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ: $share.config.document.CONT_GL_SEQ,
    FILE_ID:data.FILE_ID
}

sUtils.multipart.send(config, params);


var data = $(this.context).parents('.file-item-container')[0]._data;
if(id == "rename"){
    doFileRename(data);
}else if(id == "download"){
    doFileDownload(data);
}else if(id == "preview"){
    doFilePreview(data);
}


if ($('#cont_method_box option:selected').val() == '0') {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0016'));
    return false;
}

if ($('.file-item-status-WAITING').length > 0){
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0017'));
    return false;
}

if ($('.file-item-status-ERROR').length > 0){
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0018'));
    return false;
}

if ($share.container.contractList.children.length <= 0 ){
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0019'));
    return false;
}

return true;
